import re
import ipaddress
import urllib.parse
from flask import Flask, request, jsonify
import requests
import hashlib
import hmac
import os

app = Flask(__name__)
SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-secret-key-change-me')

ALLOWED_SCHEMES = {'http', 'https'}
BLOCKED_RANGES = [
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
]

def verify_request_signature(payload, signature):
    """Verify HMAC signature of incoming request."""
    if not signature:
        return False
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

def is_ip_blocked(hostname):
    """Check if the resolved IP is in a blocked range."""
    try:
        addr = ipaddress.ip_address(hostname)
        return any(addr in network for network in BLOCKED_RANGES)
    except ValueError:
        # Not an IP literal, need to resolve
        import socket
        try:
            resolved = socket.gethostbyname(hostname)
            addr = ipaddress.ip_address(resolved)
            return any(addr in network for network in BLOCKED_RANGES)
        except socket.gaierror:
            return True  # Block unresolvable hosts

def validate_url(url):
    """Validate that URL is safe to fetch."""
    parsed = urllib.parse.urlparse(url)

    # Check scheme
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Invalid scheme"

    # Extract hostname
    hostname = parsed.hostname
    if not hostname:
        return False, "No hostname found"

    # Block localhost variations
    if hostname in ('localhost', '0.0.0.0'):
        return False, "Localhost not allowed"

    # Validate hostname format - allow alphanumeric, dots, hyphens
    if not re.match(r'^[a-zA-Z0-9._-]+$', hostname):
        return False, "Invalid hostname characters"

    # Check IP ranges
    if is_ip_blocked(hostname):
        return False, "Blocked IP range"

    return True, "OK"

def fetch_webhook_target(url, event_data):
    """Fetch the webhook URL with event data."""
    # Re-validate before fetch (defense in depth)
    safe, reason = validate_url(url)
    if not safe:
        return None, reason

    # Perform the actual request
    try:
        resp = requests.post(
            url,
            json=event_data,
            timeout=5,
            allow_redirects=False
        )
        return resp.status_code, resp.text[:500]
    except requests.RequestException as e:
        return None, str(e)

@app.route('/api/webhook/register', methods=['POST'])
def register_webhook():
    """Register a new webhook endpoint."""
    data = request.get_json()
    if not data or 'url' not in data:
        return jsonify({'error': 'URL required'}), 400

    url = data['url']
    safe, reason = validate_url(url)
    if not safe:
        return jsonify({'error': f'Invalid URL: {reason}'}), 400

    # Store webhook (simplified)
    webhook_id = hashlib.sha256(url.encode()).hexdigest()[:16]
    return jsonify({'id': webhook_id, 'url': url, 'status': 'registered'}), 201

@app.route('/api/webhook/test', methods=['POST'])
def test_webhook():
    """Test a webhook by sending a sample event."""
    data = request.get_json()
    if not data or 'url' not in data:
        return jsonify({'error': 'URL required'}), 400

    url = data['url']

    # Normalize URL before validation
    # Replace backslashes with forward slashes for consistency
    normalized_url = url.replace('\\', '/')

    safe, reason = validate_url(normalized_url)
    if not safe:
        return jsonify({'error': f'Invalid URL: {reason}'}), 400

    # Send test event using the ORIGINAL url (preserving user's format)
    event_data = {'type': 'test', 'timestamp': '2024-01-01T00:00:00Z'}
    status, body = fetch_webhook_target(url, event_data)

    if status is None:
        return jsonify({'error': body}), 502
    return jsonify({'status': status, 'response': body}), 200

@app.route('/api/webhook/deliver', methods=['POST'])
def deliver_event():
    """Deliver an event to a registered webhook."""
    sig = request.headers.get('X-Signature')
    if not verify_request_signature(request.data, sig):
        return jsonify({'error': 'Invalid signature'}), 401

    data = request.get_json()
    url = data.get('url')
    event = data.get('event', {})

    if not url:
        return jsonify({'error': 'URL required'}), 400

    status, body = fetch_webhook_target(url, event)
    if status is None:
        return jsonify({'error': body}), 502
    return jsonify({'status': status}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
